"""
Authentication Service
JWT-based authentication for user management and authorization
"""
import jwt
import datetime
import secrets
import os
import hashlib
from typing import Optional
from functools import wraps
from flask import request, jsonify
from data.storage import storage


class AuthService:
    """Service for JWT authentication and authorization"""

    SECRET_KEY = os.environ.get('JWT_SECRET_KEY', secrets.token_urlsafe(32))
    ALGORITHM = 'HS256'
    ACCESS_TOKEN_EXPIRE_MINUTES = 60

    @staticmethod
    def _hash_password(password: str) -> str:
        """Hash password using SHA-256"""
        return hashlib.sha256(password.encode()).hexdigest()

    @staticmethod
    def _init_default_users():
        """Initialize some default users for testing"""
        try:
            existing = storage.get_all_users()
            if existing:
                return

            AuthService.register_user('user@example.com', 'password123', 'user123')
            AuthService.register_user('admin@example.com', 'admin123', 'admin123')
            AuthService.add_to_admin_group('admin123')
        except Exception as e:
            print(f"Warning: Could not initialize default users: {str(e)}")

    @staticmethod
    def register_user(email: str, password: str, user_id: Optional[str] = None) -> dict:
        """
        Register a new user.

        Raises ValueError if user already exists.
        """
        existing = storage.get_user_by_email(email)
        if existing:
            raise ValueError(f"User with email {email} already exists")

        if user_id is None:
            user_id = secrets.token_urlsafe(16)

        user = {
            'sub': user_id,
            'email': email,
            'password_hash': AuthService._hash_password(password),
            'groups': [],
            'created_at': datetime.datetime.utcnow().isoformat()
        }

        storage.create_user(user)

        return {
            'sub': user['sub'],
            'email': user['email'],
            'message': 'User registered successfully'
        }

    @staticmethod
    def authenticate_user(email: str, password: str) -> Optional[dict]:
        """Authenticate user credentials. Returns user dict if valid, None otherwise."""
        user = storage.get_user_by_email(email)
        if not user:
            return None

        if user.get('password_hash') == AuthService._hash_password(password):
            return user

        return None

    @staticmethod
    def create_access_token(user: dict) -> str:
        """Create JWT access token"""
        expire = datetime.datetime.utcnow() + datetime.timedelta(
            minutes=AuthService.ACCESS_TOKEN_EXPIRE_MINUTES
        )

        payload = {
            'sub': user['sub'],
            'email': user['email'],
            'groups': user.get('groups', []),
            'exp': expire,
            'iat': datetime.datetime.utcnow(),
            'token_use': 'id'
        }

        return jwt.encode(payload, AuthService.SECRET_KEY, algorithm=AuthService.ALGORITHM)

    @staticmethod
    def decode_token(token: str) -> Optional[dict]:
        """Decode and validate JWT token. Returns payload or None."""
        try:
            return jwt.decode(
                token,
                AuthService.SECRET_KEY,
                algorithms=[AuthService.ALGORITHM]
            )
        except (jwt.ExpiredSignatureError, jwt.InvalidTokenError):
            return None

    @staticmethod
    def get_user_from_token(token: str) -> Optional[dict]:
        """Get user record from database using token's sub claim."""
        payload = AuthService.decode_token(token)
        if not payload:
            return None
        return storage.get_user(payload['sub'])

"""
Airline Booking Monolithic Application
A traditional web application combining all booking services
"""
from flask import Flask, request, jsonify
from flask_cors import CORS
import sys
import os

# Add current directory to Python path
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from services.catalog import CatalogService
from services.booking import BookingService
from services.payment import PaymentService
from services.loyalty import LoyaltyService
from services.auth import AuthService, login_required, admin_required, owner_or_admin_required, booking_owner_or_admin_required
from data.storage import storage

# Configure Flask with static file serving
app = Flask(__name__)

# Enable CORS for development
CORS(app)


# Error handler
@app.errorhandler(Exception)
def handle_error(error):
    """Global error handler"""
    return jsonify({
        'error': str(error),
        'type': type(error).__name__
    }), 400 if isinstance(error, ValueError) else 500


# Catalog endpoints
@app.route('/flights/search', methods=['GET'])
def search_flights():
    """
    Search for flights
    Query params: departureCode, arrivalCode, departureDate
    """
    departure_code = request.args.get('departureCode')
    arrival_code = request.args.get('arrivalCode')
    departure_date = request.args.get('departureDate')

    if not all([departure_code, arrival_code, departure_date]):
        return jsonify({'error': 'Missing required parameters'}), 400

    flights = CatalogService.search_flights(departure_code, arrival_code, departure_date)
    return jsonify({'flights': flights})


@app.route('/flights/<flight_id>', methods=['GET'])
def get_flight(flight_id):
    """Get flight details by ID"""
    flight = CatalogService.get_flight(flight_id)
    return jsonify(flight)


